// ============================================================================
// DATA SUBJECT REQUESTS (GDPR)
// ============================================================================

/**
 * Create a data subject request — persists to DB and in-memory map.
 */
async createDSR(params: {
  orgId: string;
  subjectId: string;
  subjectEmail: string;
  requestType: DataSubjectRequest["requestType"];
}): Promise<DataSubjectRequest> {
  const now = new Date();
  const deadline = new Date(now.getTime() + this.dsrDeadlineDays * 24 * 60 * 60 * 1000);

  const request: DataSubjectRequest = {
    requestId: crypto.randomUUID(),
    orgId: params.orgId,
    subjectId: params.subjectId,
    subjectEmail: params.subjectEmail,
    requestType: params.requestType,
    requestedAt: now,
    deadline,
    status: "pending",
    completedAt: null,
    result: null,
    processedBy: null,
    notes: "",
  };

  // Persist to database
  try {
    const db = await getDb();
    await db.insert(dataSubjectRequests).values({
      id: request.requestId,
      orgId: request.orgId,
      subjectId: request.subjectId,
      subjectEmail: request.subjectEmail,
      requestType: request.requestType,
      status: request.status,
      deadline: request.deadline,
      notes: request.notes,
    });
  } catch (err) {
    // Log but don't fail — keep in-memory fallback
    this.logAudit("DSR_DB_WRITE_FAILED", "system", `Failed to persist DSR to DB: ${(err as Error).message}`, params.subjectId);
  }

  this.requests.set(request.requestId, request);
  this.logAudit("DSR_CREATED", "system", `DSR ${params.requestType} created for subject ${params.subjectId}`, params.subjectId);

  return request;
}

/**
 * Process a data subject request — performs real DB queries/deletes and
 * updates the DSR status in the database.
 */
async processDSR(requestId: string, processedBy: string): Promise<DataSubjectRequest> {
  const request = this.requests.get(requestId);
  if (!request) {
    throw new Error(`DSR ${requestId} not found`);
  }

  if (request.status !== "pending") {
    throw new Error(`DSR ${requestId} is not pending`);
  }

  request.status = "processing";
  request.processedBy = processedBy;

  // Update DB status to "processing"
  await this.updateDSRInDb(requestId, { status: "processing", processedBy });

  // Process based on type
  switch (request.requestType) {

